  function makeButton(label,action,value,cls){const b=document.createElement('button');b.type='button';b.className=cls||'choice-btn';b.textContent=label;b.dataset.action=action;b.dataset.value=value==null?'':value;b.dataset.label=label;if(state.mode==='text')b.tabIndex=-1;return b;}
