  function autoPick(kind){if(state.mode!=='text')return;const e=expected();if(!e)return;const buttons=Array.from(chat.querySelectorAll('[data-action]')).filter(function(b){return !b.disabled&&b.dataset.action===e[0]&&String(b.dataset.value||'')===String(e[1]);});const b=buttons[buttons.length-1];if(!b)return;b.dataset.label=ax(e[2])||b.dataset.label;const token=state.token;later(function(){if(!state.awaiting||b.disabled)return;b.classList.add('demo-pick');const card=b.closest('.cc-card');if(card)card.classList.add('demo-selected');state.demoIndex+=1;later(function(){if(state.awaiting&&!b.disabled)b.click();},500,token);},kind==='rich'?1300:800,token);}
