  function start(){newSession();root.dataset.mode=state.mode;document.querySelectorAll('.mode-btn').forEach(function(b){const active=b.dataset.mode===state.mode;b.classList.toggle('active',active);b.setAttribute('aria-selected',String(active));});document.getElementById('langSelect').value=state.lang;document.getElementById('modalTitle').textContent=tx(META[state.flow].title);document.getElementById('modalAvatar').textContent=META[state.flow].icon;document.getElementById('modalSub').textContent='● '+tx('online');document.getElementById('chatInput').placeholder=state.mode==='text'?tx('autoHint'):tx('inputHint');buildSteps();addDate();if(state.flow===0)reply(tx('courseGreeting'),function(){choices([{label:tx('undergraduate'),action:'course-level',value:'ug'},{label:tx('postgraduate'),action:'course-level',value:'pg'}]);});if(state.flow===1)reply(tx('appGreeting'),function(){choices([{label:tx('checkStatus'),action:'app-start',value:'status'},{label:tx('requiredDocs'),action:'app-start',value:'documents'},{label:tx('uploadDoc'),action:'app-start',value:'upload'},{label:tx('contactAdmissions'),action:'app-start',value:'contact'}]);});if(state.flow===2)reply(tx('eventGreeting'),function(){choices([{label:tx('announcements'),action:'updates-start',value:'announcements'},{label:tx('webinars'),action:'updates-start',value:'webinars'},{label:tx('openHouse'),action:'updates-start',value:'open-house'},{label:tx('campusTours'),action:'updates-start',value:'campus'}]);});if(state.flow===3)reply(tx('counselGreeting'),function(){choices([{label:tx('phoneCounsel'),action:'counsel-mode',value:'phone'},{label:tx('videoCounsel'),action:'counsel-mode',value:'video'},{label:tx('campusVisit'),action:'counsel-mode',value:'campus'}]);});if(state.flow===4)reply(tx('recoveryGreeting'),function(){reply(tx('concernQuestion'),function(){choices([{label:tx('eligibilityConcern'),action:'recovery-concern',value:'eligibility'},{label:tx('feeConcern'),action:'recovery-concern',value:'fees'},{label:tx('documentConcern'),action:'recovery-concern',value:'documents'},{label:tx('counsellingConcern'),action:'recovery-concern',value:'counselling'},{label:tx('decidingConcern'),action:'recovery-concern',value:'deciding'}]);});});}

  function handleCourse(a,v){if(a==='course-level'){state.data.programmeLevel=v;setStep(0);reply(tx('areaQuestion'),function(){choices([{label:tx('engineering'),action:'course-area',value:'engineering'},{label:tx('business'),action:'course-area',value:'business'},{label:tx('commerce'),action:'course-area',value:'commerce'},{label:tx('computers'),action:'course-area',value:'computers'},{label:tx('science'),action:'course-area',value:'science'}]);});}else if(a==='course-area'){state.data.interestArea=v;reply(tx('qualQuestion'),function(){choices([{label:tx('completed'),action:'course-qual',value:'completed'},{label:tx('appearing'),action:'course-qual',value:'appearing'}]);});}else if(a==='course-qual'){state.data.qualification=v;reply(tx('streamQuestion'),function(){const opts=state.data.programmeLevel==='ug'?[{label:'PCM',value:'pcm'},{label:'PCB',value:'pcb'},{label:tx('commerce'),value:'commerce'},{label:'Arts / Humanities',value:'arts'}]:[{label:'Engineering',value:'engineering'},{label:tx('commerce'),value:'commerce'},{label:tx('science'),value:'science'},{label:'Other Bachelor’s',value:'other'}];choices(opts.map(function(x){return{label:x.label,action:'course-stream',value:x.value};}));});}else if(a==='course-stream'){state.data.stream=v;reply(tx('marksQuestion'),function(){choices(['below50','50-59','60-69','70-79','80+'].map(function(x){return{label:x==='below50'?'Below 50%':x+'%',action:'course-marks',value:x};}));});}else if(a==='course-marks'){state.data.percentage=v;setStep(1);reply(tx('recommendations'),function(){richCards(courseList(),'select-course','select');});}else if(a==='select-course'){state.data.selectedCourse=COURSES.find(function(c){return c.id===v;});setStep(2);reply(tx('courseChosen'),function(){summary(state.data.selectedCourse.title,state.data.selectedCourse.level==='ug'?tx('undergraduate'):tx('postgraduate'),[[tx('duration'),state.data.selectedCourse.duration],[tx('mode'),state.data.selectedCourse.mode],[tx('campus'),state.data.selectedCourse.campus],[tx('fee'),state.data.selectedCourse.fee],[tx('intake'),'2027 Admissions']],[], '', '🎓');courseMenu();});}else if(a==='course-detail'){setStep(v==='eligibility'?2:3);const key=v==='eligibility'?(profileAppearsEligible()?'eligibilityAnswer':'eligibilityReview'):v==='fees'?'feesAnswer':v==='scholarship'?'scholarshipAnswer':'detailsAnswer';reply(v==='fees'?fmt(key,{fee:state.data.selectedCourse.fee}):tx(key),courseMenu);}else if(a==='course-contact'){reply(tx('contactQuestion'),function(){choices([{label:tx('yesContact'),action:'lead-start',value:'yes'},{label:tx('continueExploring'),action:'course-detail',value:'details'}]);});}else if(a==='lead-start'){leadStart('course');}else if(a==='lead-name'){state.data.studentName=v;reply(fmt('askMobile',{name:v}),function(){choices([{label:'9876543210',action:'lead-mobile',value:'9876543210'}]);});}else if(a==='lead-mobile'){state.data.mobile=v;reply(tx('askEmail'),function(){choices([{label:'arjun.kumar@example.com',action:'lead-email',value:'arjun.kumar@example.com'}]);});}else if(a==='lead-email'){state.data.email=v;leadReview();}else if(a==='lead-form'){const d=JSON.parse(v);state.data.studentName=d.name;state.data.mobile=d.mobile;state.data.email=d.email;leadReview();}else if(a==='lead-submit'){finishLead();}}
  function handleApp(a,v){if(a==='app-start'&&v==='status'){setStep(0);reply(tx('appIdAsk'),function(){choices([{label:'APP-2027-1842',action:'app-id',value:'APP-2027-1842'}]);});}else if(a==='app-start'&&(v==='documents'||v==='upload')){setStep(2);reply(tx('appFound'),function(){statusCard([{label:'Class 10 Marksheet',done:true},{label:'Identity Document',done:true},{label:'Class 12 Marksheet',current:true}],[{label:tx('uploadDoc'),action:'app-upload',value:'marksheet'}]);});}else if(a==='app-start'&&v==='contact'){handleApp('app-contact','');}else if(a==='app-id'){state.data.applicationId=v;reply(tx('appFound'),applicationStatus);}else if(a==='app-upload'){setStep(2);const w=document.createElement('div');w.appendChild(makeButton('📎 '+tx('uploadDoc'),'app-upload-confirm','marksheet','upload-btn'));insert(w);state.awaiting=true;autoPick('rich');}else if(a==='app-upload-confirm'){reply(tx('documentReceived'),function(){statusCard([{label:tx('submitted'),done:true},{label:tx('feePaid'),done:true},{label:'Class 12 Marksheet · '+tx('reviewPending'),current:true}],[{label:tx('contactAdmissions'),action:'app-contact'}]);});}else if(a==='app-contact'){setStep(3);reply(tx('supportCreated'),function(){summary(tx('contactAdmissions'),tx('referenceId')+' · EDU-SUP-1842',[[tx('application'),'APP-2027-1842'],[tx('status'),tx('reviewPending')]],[], '', '✓');});}}
  function handleEvent(a,v){if(a==='updates-start'){setStep(1);reply(tx('eventGreeting'),function(){richCards(EVENTS,'select-event','register');});}else if(a==='select-event'){state.data.event=EVENTS.find(function(e){return e.id===v;});setStep(2);reply(tx('registerQuestion'),function(){summary(state.data.event.title,state.data.event.tag,[[tx('date'),state.data.event.sub],[tx('mode'),state.data.event.meta]],[{label:tx('courseDetails'),action:'event-details'},{label:tx('register'),action:'event-register'}],'','📅');});}else if(a==='event-details'){reply(tx('eventCoverage'),function(){choices([{label:tx('register'),action:'event-register',value:''}]);});}else if(a==='event-register'){setStep(3);eventForm();}else if(a==='event-name'){state.data.studentName=v;reply(fmt('askMobile',{name:v}),function(){choices([{label:'9876543210',action:'event-mobile',value:'9876543210'}]);});}else if(a==='event-mobile'){state.data.mobile=v;reply(tx('askEmail'),function(){choices([{label:'arjun.kumar@example.com',action:'event-email',value:'arjun.kumar@example.com'}]);});}else if(a==='event-email'){state.data.email=v;eventReview();}else if(a==='reg-form'){const d=JSON.parse(v);state.data.studentName=d.name;state.data.mobile=d.mobile;state.data.email=d.email;finishEvent();}else if(a==='reg-submit'){finishEvent();}}
  function handleCounsel(a,v){if(a==='counsel-mode'){state.data.counsellingMode=v;setStep(2);if(v==='campus')reply(tx('campusQuestion'),function(){richCards(CAMPUSES,'select-campus','choose');});else{state.data.campus={title:v==='phone'?tx('phoneCounsel'):tx('videoCounsel')};reply(tx('visitDate'),function(){datePicker('counsel-date');});}}else if(a==='select-campus'){state.data.campus=CAMPUSES.find(function(c){return c.id===v;});setStep(3);reply(tx('visitDate'),function(){datePicker('counsel-date');});}else if(a==='counsel-date'){state.data.date=v;reply(tx('visitSlot'),function(){slotPicker('counsel-slot');});}else if(a==='counsel-slot'){state.data.slot=v;reply(tx(state.data.counsellingMode==='campus'?'visitDetails':'sessionDetails'),visitForm);}else if(a==='visit-name'){state.data.studentName=v;reply(fmt('askMobile',{name:v}),function(){choices([{label:'9876543210',action:'visit-mobile',value:'9876543210'}]);});}else if(a==='visit-mobile'){state.data.mobile=v;reply(tx('askEmail'),function(){choices([{label:'arjun.kumar@example.com',action:'visit-email',value:'arjun.kumar@example.com'}]);});}else if(a==='visit-email'){state.data.email=v;state.data.programme='BBA';visitReview();}else if(a==='visit-form'){const d=JSON.parse(v);state.data.studentName=d.name;state.data.mobile=d.mobile;state.data.email=d.email;state.data.programme=d.programme;finishVisit();}else if(a==='visit-submit'){finishVisit();}}
  function handleRecovery(a,v){if(a==='recovery-concern'){state.data.concern=v;setStep(2);const branch={eligibility:'recoveryEligibility',fees:'recoveryFees',documents:'recoveryDocuments',counselling:'recoveryCounselling',deciding:'recoveryDeciding'}[v]||'recoveryResolve';reply(tx(branch),function(){reply(tx('recoveryNext'),function(){choices([{label:tx('resumeApplication'),action:'recovery-next',value:'resume'},{label:tx('talkCounsellor'),action:'recovery-next',value:'counsellor'}]);});});}else if(a==='recovery-next'){setStep(3);reply(tx('recoveryFinal'),function(){statusCard([{label:tx('personalDone'),done:true},{label:tx('programmeDone'),done:true},{label:tx('academicsDone'),done:true},{label:tx('docsPending'),current:true},{label:tx('finalPending')}],[]);});}}

  function formData(button){const f=button.closest('.details-form');if(!f)return null;const out={};let valid=true;f.querySelectorAll('input').forEach(function(i){const val=i.value.trim();if(!val)valid=false;out[i.name]=val;});return valid?out:null;}
  function processAction(button){if(!state.awaiting||state.processing||button.disabled)return;state.processing=true;state.awaiting=false;let a=button.dataset.action;let v=button.dataset.value||'';let label=button.dataset.label||button.textContent.trim();if(['lead-form','reg-form','visit-form'].includes(a)){const d=formData(button);if(!d){state.processing=false;state.awaiting=true;return;}v=JSON.stringify(d);label=d.name+' · '+d.mobile;}disable();addMessage('user',label);state.processing=false;if(state.flow===0)handleCourse(a,v);if(state.flow===1)handleApp(a,v);if(state.flow===2)handleEvent(a,v);if(state.flow===3)handleCounsel(a,v);if(state.flow===4)handleRecovery(a,v);}
  function openFlow(index){state.flow=Number(index);state.mode='text';state.lang='en';modal.classList.add('open');modal.setAttribute('aria-hidden','false');document.body.style.overflow='hidden';start();}
  function close(){clearTimers();state.token+=1;state.awaiting=false;modal.classList.remove('open');modal.setAttribute('aria-hidden','true');document.body.style.overflow='';}
  function switchMode(mode){if(!['text','structured'].includes(mode)||state.mode===mode)return;state.mode=mode;start();}
  function switchLang(lang){if(!LANGS.includes(lang)||state.lang===lang)return;state.lang=lang;start();}

